% Strong
\newcommand\mdstrong[1]{\textbf{#1}}

% Code
\newcommand\mdcode[1]{\texttt{#1}}

% Rule
% Default impl : (displays centered asterisks)
\newcommand\mdrule{
  \nopagebreak
  {\vskip 1em}
  \nopagebreak
  \begin{center}
    ***
  \end{center}
  \nopagebreak
