//! A small YAML subset parser, sufficient for book configuration files and
//! inline metadata blocks.

use std::fmt;

#[derive(Clone, PartialEq)]
pub enum Yaml {
    Real(String),
    Integer(i64),
    String(String),
    Boolean(bool),
    Array(Vec<Yaml>),
    Hash(Vec<(Yaml, Yaml)>),
    Null,
    BadValue,
}

impl fmt::Debug for Yaml {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match *self {
            Yaml::Real(ref s) => write!(f, "Real({:?})", s),
            Yaml::Integer(i) => write!(f, "Integer({})", i),
            Yaml::String(ref s) => write!(f, "String({:?})", s),
            Yaml::Boolean(b) => write!(f, "Boolean({})", b),
            Yaml::Array(ref v) => {
                write!(f, "Array(")?;
                f.debug_list().entries(v.iter()).finish()?;
                write!(f, ")")
            }
            Yaml::Hash(ref h) => {
                write!(f, "Hash(")?;
                let mut first = true;
                write!(f, "{{")?;
                for (k, v) in h {
                    if !first {
                        write!(f, ", ")?;
                    }
                    first = false;
                    write!(f, "{:?}: {:?}", k, v)?;
                }
                write!(f, "}}")?;
                write!(f, ")")
            }
            Yaml::Null => write!(f, "Null"),
            Yaml::BadValue => write!(f, "BadValue"),
        }
    }
}

impl Yaml {
    pub fn as_str(&self) -> Option<&str> {
        match *self {
            Yaml::String(ref s) => Some(s),
            _ => None,
        }
    }
}

/// Parse a plain (unquoted) scalar into a typed Yaml value
fn parse_plain(s: &str) -> Yaml {
    match s {
        "~" | "null" | "Null" | "NULL" | "" => return Yaml::Null,
        "true" | "True" | "TRUE" => return Yaml::Boolean(true),
        "false" | "False" | "FALSE" => return Yaml::Boolean(false),
        _ => {}
    }
    if let Some(hex) = s.strip_prefix("0x") {
        if let Ok(i) = i64::from_str_radix(hex, 16) {
            return Yaml::Integer(i);
        }
    }
    if let Some(oct) = s.strip_prefix("0o") {
        if let Ok(i) = i64::from_str_radix(oct, 8) {
            return Yaml::Integer(i);
        }
    }
    if let Ok(i) = s.parse::<i64>() {
        return Yaml::Integer(i);
    }
    if s.parse::<f64>().is_ok() && s.chars().any(|c| c == '.' || c == 'e' || c == 'E') {
        return Yaml::Real(s.to_string());
    }
    Yaml::String(s.to_string())
}

pub struct YamlError {
    pub msg: String,
}

impl YamlError {
    fn new(msg: String) -> YamlError {
        YamlError { msg }
    }
}

struct Line<'a> {
    indent: usize,
    content: &'a str,
    number: usize,
}

/// Load a YAML document. Only the subset used by Crowbook books is supported.
pub fn load(input: &str) -> Result<Vec<Yaml>, YamlError> {
    let mut lines: Vec<Line> = Vec::new();
    let mut has_doc_start = false;
    for (i, raw) in input.lines().enumerate() {
        let trimmed_end = raw.trim_end();
        let stripped = strip_comment(trimmed_end);
        if stripped.trim().is_empty() {
            continue;
        }
        if stripped.trim() == "---" {
            has_doc_start = true;
            continue;
        }
        if stripped.trim() == "..." {
            continue;
        }
        let indent = stripped.len() - stripped.trim_start().len();
        // Reject constructs we do not want to silently mis-parse
        let c = stripped.trim_start();
        if let Some(first) = c.chars().next() {
            match first {
                '%' => {
                    return Err(YamlError::new(format!(
                        "while scanning a directive, could not find expected directive name at line {} column {}",
                        i + 1,
                        indent + 2
                    )))
                }
                '*' => {
                    return Err(YamlError::new(format!(
                        "while scanning an anchor or alias, did not find expected alphabetic or numeric character at line {} column {}",
                        i + 1,
                        indent + 1
                    )))
                }
                '>' | '|' => {
                    return Err(YamlError::new(format!(
                        "while scanning a block scalar, did not find expected comment or line break at line {} column {}",
                        i + 1,
                        indent + 1
                    )))
                }
                '@' | '`' => {
                    return Err(YamlError::new(format!(
                        "while scanning for the next token, found character that cannot start any token at line {} column {}",
                        i + 1,
                        indent + 1
                    )))
                }
                _ => {}
            }
        }
        lines.push(Line {
            indent,
            content: c,
            number: i + 1,
        });
    }
    let _ = has_doc_start;
    if lines.is_empty() {
        return Ok(vec![]);
    }
    let mut pos = 0;
    let value = parse_block(&lines, &mut pos, lines[0].indent)?;
    if pos < lines.len() {
        return Err(YamlError::new(format!(
            "mapping values are not allowed in this context at line {} column {}",
            lines[pos].number,
            lines[pos].indent + 1
        )));
    }
    Ok(vec![value])
}

fn strip_comment(line: &str) -> &str {
    // A '#' starts a comment when at the beginning of the line or preceded by a space
    let bytes = line.as_bytes();
    let mut in_single = false;
    let mut in_double = false;
    for (i, &b) in bytes.iter().enumerate() {
        match b {
            b'\'' if !in_double => in_single = !in_single,
            b'"' if !in_single => in_double = !in_double,
            b'#' if !in_single && !in_double => {
                if i == 0 || bytes[i - 1] == b' ' || bytes[i - 1] == b'\t' {
                    return &line[..i];
                }
            }
            _ => {}
        }
    }
    line
}

fn parse_block(lines: &[Line], pos: &mut usize, indent: usize) -> Result<Yaml, YamlError> {
    if *pos >= lines.len() {
        return Ok(Yaml::Null);
    }
    if lines[*pos].content.starts_with("- ") || lines[*pos].content == "-" {
        let mut arr = Vec::new();
        while *pos < lines.len() && lines[*pos].indent == indent {
            let content = lines[*pos].content;
            if !(content.starts_with("- ") || content == "-") {
                break;
            }
            let rest = if content == "-" { "" } else { &content[2..] };
            *pos += 1;
            if rest.trim().is_empty() {
                if *pos < lines.len() && lines[*pos].indent > indent {
                    let sub = lines[*pos].indent;
                    arr.push(parse_block(lines, pos, sub)?);
                } else {
                    arr.push(Yaml::Null);
                }
            } else {
                arr.push(parse_scalar_or_inline(rest)?);
            }
        }
        return Ok(Yaml::Array(arr));
    }
    let mut hash: Vec<(Yaml, Yaml)> = Vec::new();
    while *pos < lines.len() && lines[*pos].indent == indent {
        let content = lines[*pos].content;
        let (key, rest) = match split_key(content) {
            Some(x) => x,
            None => {
                if hash.is_empty() {
                    let v = parse_scalar_or_inline(content)?;
                    *pos += 1;
                    return Ok(v);
                }
                return Err(YamlError::new(format!(
                    "could not find expected ':' at line {} column {}",
                    lines[*pos].number,
                    lines[*pos].content.len() + lines[*pos].indent + 1
                )));
            }
        };
        *pos += 1;
        let value = if rest.trim().is_empty() {
            if *pos < lines.len() && lines[*pos].indent > indent {
                let sub = lines[*pos].indent;
                parse_block(lines, pos, sub)?
            } else if *pos < lines.len()
                && lines[*pos].indent == indent
                && (lines[*pos].content.starts_with("- ") || lines[*pos].content == "-")
            {
                parse_block(lines, pos, indent)?
            } else {
                Yaml::Null
            }
        } else {
            parse_scalar_or_inline(rest)?
        };
        hash.push((parse_key(&key), value));
    }
    Ok(Yaml::Hash(hash))
}

fn parse_key(key: &str) -> Yaml {
    let k = key.trim();
    if (k.starts_with('"') && k.ends_with('"') && k.len() >= 2)
        || (k.starts_with('\'') && k.ends_with('\'') && k.len() >= 2)
    {
        Yaml::String(unquote(k))
    } else {
        parse_plain(k)
    }
}

/// Split `key: value`; returns None if there is no mapping separator
fn split_key(content: &str) -> Option<(String, &str)> {
    let bytes = content.as_bytes();
    let mut in_single = false;
    let mut in_double = false;
    let mut depth = 0;
    for i in 0..bytes.len() {
        match bytes[i] {
            b'\'' if !in_double => in_single = !in_single,
            b'"' if !in_single => in_double = !in_double,
            b'[' | b'{' if !in_single && !in_double => depth += 1,
            b']' | b'}' if !in_single && !in_double => depth -= 1,
            b':' if !in_single && !in_double && depth == 0 => {
                if i + 1 == bytes.len() {
                    return Some((content[..i].to_string(), ""));
                }
                if bytes[i + 1] == b' ' || bytes[i + 1] == b'\t' {
                    return Some((content[..i].to_string(), &content[i + 1..]));
                }
            }
            _ => {}
        }
    }
    None
}

fn unquote(s: &str) -> String {
    let inner = &s[1..s.len() - 1];
    if s.starts_with('\'') {
        inner.replace("''", "'")
    } else {
        let mut out = String::new();
        let mut chars = inner.chars();
        while let Some(c) = chars.next() {
            if c == '\\' {
                match chars.next() {
                    Some('n') => out.push('\n'),
                    Some('t') => out.push('\t'),
                    Some('r') => out.push('\r'),
                    Some('\\') => out.push('\\'),
                    Some('"') => out.push('"'),
                    Some(other) => out.push(other),
                    None => {}
                }
            } else {
                out.push(c);
            }
        }
        out
    }
}

fn parse_scalar_or_inline(s: &str) -> Result<Yaml, YamlError> {
    let t = s.trim();
    if t.starts_with('[') {
        let inner = t
            .strip_prefix('[')
            .and_then(|x| x.strip_suffix(']'))
            .unwrap_or("");
        let mut arr = Vec::new();
        for item in split_flow(inner) {
            let item = item.trim();
            if item.is_empty() {
                continue;
            }
            arr.push(parse_scalar_or_inline(item)?);
        }
        return Ok(Yaml::Array(arr));
    }
    if t.starts_with('{') {
        let inner = t
            .strip_prefix('{')
            .and_then(|x| x.strip_suffix('}'))
            .unwrap_or("");
        let mut hash = Vec::new();
        for item in split_flow(inner) {
            let item = item.trim();
            if item.is_empty() {
                continue;
            }
            if let Some((k, v)) = split_key(item) {
                hash.push((parse_key(&k), parse_scalar_or_inline(v)?));
            }
        }
        return Ok(Yaml::Hash(hash));
    }
    if (t.starts_with('"') && t.ends_with('"') && t.len() >= 2)
        || (t.starts_with('\'') && t.ends_with('\'') && t.len() >= 2)
    {
        return Ok(Yaml::String(unquote(t)));
    }
