//! Runtime and output localization.

/// Language used for the messages Crowbook itself prints
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum UiLang {
    En,
    Fr,
}

static mut UI_LANG: UiLang = UiLang::En;

pub fn set_ui_lang(lang: &str) {
    let l = if lang.len() >= 2 { &lang[..2] } else { lang };
    let l = l.to_lowercase();
    unsafe {
        UI_LANG = if l == "fr" { UiLang::Fr } else { UiLang::En };
    }
}

pub fn ui_lang() -> UiLang {
    unsafe { UI_LANG }
}

/// Translate a message identified by its english version
pub fn lformat(en: &str) -> &'static str {
    if ui_lang() == UiLang::En {
        return leak(en);
    }
    for &(key, fr) in FR_MESSAGES {
        if key == en {
            return fr;
        }
    }
    leak(en)
}

fn leak(s: &str) -> &'static str {
    // The set of strings passed here is a small fixed set of literals
    Box::leak(s.to_string().into_boxed_str())
}

static FR_MESSAGES: &[(&str, &str)] = &[
    (
        "Could not find file '{}' for {}",
        "Impossible de trouver le fichier '{}' pour {}",
    ),
    (
        "Error parsing configuration file: ",
        "Erreur dans l'analyse du fichier de configuration : ",
    ),
    ("no chapter name specified", "pas de nom de chapitre spécifié"),
    (
        "found invalid chapter definition in the chapter list",
        "définition de chapitre invalide trouvée dans la liste des chapitres",
    ),
    (
        "found invalid part definition in the chapter list",
        "définition de partie invalide trouvée dans la liste des chapitres",
    ),
    (
        "Error converting BookOption: ",
        "Erreur en convertissant l'option de livre :",
    ),
    ("Error rendering {}: ", "Erreur dans le rendu de {}: "),
    (
        "Error during temporary files editing: ",
        "Erreur durant l'édition de fichiers temporaires :",
    ),
    (
        "could not create file '{}': '{}",
        "could not create file '{}': '{}",
    ),
    (
        "YAML block was not valid YAML: {}",
        "le bloc YAML n'était pas du YAML valide : {}",
    ),
    (
        "Error initializing book: {}",
        "Erreur à l'initialisation du livre : {}",
    ),
];

/// Strings used in the generated documents, depending on the book's language
pub struct OutputLang {
    pub code: &'static str,
    pub toc: &'static str,
    pub chapter: &'static str,
    pub part: &'static str,
    pub notes: &'static str,
    pub title: &'static str,
    pub cover: &'static str,
    pub display_all: &'static str,
    pub display_one: &'static str,
}

static LANGS: &[OutputLang] = &[
    OutputLang {
        code: "en",
        toc: "Table of contents",
        chapter: "Chapter",
        part: "Part",
        notes: "Notes",
        title: "Title",
        cover: "Cover",
        display_all: "Display all chapters",
        display_one: "Display one chapter",
    },
    OutputLang {
        code: "fr",
        toc: "Table des matières",
        chapter: "Chapitre",
        part: "Partie",
        notes: "Notes",
        title: "Titre",
        cover: "Couverture",
        display_all: "Afficher tous les chapitres",
        display_one: "N'afficher qu'un chapitre",
    },
    OutputLang {
        code: "es",
        toc: "Índice",
        chapter: "Capítulo",
