/// Language used for the messages Crowbook itself prints
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum UiLang {
    En,
    Fr,
}

static mut UI_LANG: UiLang = UiLang::En;

pub fn set_ui_lang(lang: &str) {
    let l = if lang.len() >= 2 { &lang[..2] } else { lang };
    let l = l.to_lowercase();
    unsafe {
        UI_LANG = if l == "fr" { UiLang::Fr } else { UiLang::En };
    }
}

pub fn ui_lang() -> UiLang {
    unsafe { UI_LANG }
}

