//! A CommonMark-ish Markdown parser producing Crowbook tokens.

use crate::token::Token;
use std::collections::HashMap;

pub struct Options {
    pub superscript: bool,
}

impl Default for Options {
    fn default() -> Self {
        Options { superscript: false }
    }
}

struct LinkDef {
    dest: String,
    title: String,
}

pub struct Parser {
    opts: Options,
    links: HashMap<String, LinkDef>,
}

pub fn parse(input: &str, opts: Options) -> Vec<Token> {
    let mut p = Parser {
        opts,
        links: HashMap::new(),
    };
    let text = input.replace("\r\n", "\n").replace('\r', "\n");
    let lines: Vec<String> = text.lines().map(|l| expand_tabs(l)).collect();
    p.collect_link_defs(&lines);
    let mut tokens = p.blocks(&lines);
    merge_strs(&mut tokens);
    tokens
}

fn expand_tabs(line: &str) -> String {
    if !line.contains('\t') {
        return line.to_string();
    }
    let mut out = String::new();
    for c in line.chars() {
        if c == '\t' {
            let n = 4 - (out.chars().count() % 4);
            for _ in 0..n {
                out.push(' ');
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn indent_of(line: &str) -> usize {
    line.len() - line.trim_start().len()
}

fn is_blank(line: &str) -> bool {
    line.trim().is_empty()
}

fn is_thematic_break(line: &str) -> bool {
    let t = line.trim();
    if indent_of(line) >= 4 {
        return false;
    }
    let c = match t.chars().next() {
        Some(c) if c == '*' || c == '-' || c == '_' => c,
        _ => return false,
    };
    let mut count = 0;
    for ch in t.chars() {
        if ch == c {
            count += 1;
        } else if ch != ' ' && ch != '\t' {
            return false;
        }
    }
    count >= 3
}

fn atx_heading(line: &str) -> Option<(i32, String)> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    let hashes = t.chars().take_while(|&c| c == '#').count();
    if hashes == 0 || hashes > 6 {
        return None;
    }
    let rest = &t[hashes..];
    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') {
        return None;
    }
    let mut content = rest.trim().to_string();
    // closing sequence
    let trimmed = content.trim_end_matches('#');
    if trimmed.len() != content.len() && (trimmed.is_empty() || trimmed.ends_with(' ')) {
        content = trimmed.trim_end().to_string();
    }
    Some((hashes as i32, content))
}

fn setext_level(line: &str) -> Option<i32> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim();
    if t.is_empty() {
        return None;
    }
    if t.chars().all(|c| c == '=') {
        Some(1)
    } else if t.chars().all(|c| c == '-') {
        Some(2)
    } else {
        None
    }
}

fn fence_start(line: &str) -> Option<(char, usize, usize, String)> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = line.trim_start();
    let c = match t.chars().next() {
        Some('`') => '`',
        Some('~') => '~',
        _ => return None,
    };
    let n = t.chars().take_while(|&x| x == c).count();
    if n < 3 {
        return None;
    }
    let info = t[n..].trim().to_string();
    if c == '`' && info.contains('`') {
        return None;
    }
    Some((c, n, ind, info))
}

/// Bullet or ordered list marker: returns (is_ordered, start, marker_len, content_offset)
fn list_marker(line: &str) -> Option<(bool, usize, char, usize)> {
    let ind = indent_of(line);
    if ind >= 4 {
        return None;
    }
    let t = &line[ind..];
    let bytes = t.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let c = bytes[0] as char;
    if c == '-' || c == '+' || c == '*' {
        if is_thematic_break(line) {
            return None;
        }
        if bytes.len() == 1 {
            return Some((false, 0, c, ind + 2));
        }
        if bytes[1] == b' ' {
            let after = t[1..].len() - t[1..].trim_start().len();
            let off = if after >= 5 { 2 } else { 1 + after };
            return Some((false, 0, c, ind + off));
        }
        return None;
    }
    let digits = t.chars().take_while(|c| c.is_ascii_digit()).count();
    if digits == 0 || digits > 9 {
        return None;
    }
    let delim = bytes.get(digits).copied();
    if delim != Some(b'.') && delim != Some(b')') {
        return None;
    }
    let num: usize = t[..digits].parse().unwrap_or(0);
    if bytes.len() == digits + 1 {
        return Some((true, num, delim.unwrap() as char, ind + digits + 2));
    }
    if bytes[digits + 1] != b' ' {
        return None;
    }
    let after_marker = &t[digits + 1..];
    let spaces = after_marker.len() - after_marker.trim_start().len();
    let off = if spaces >= 5 { 1 } else { spaces };
    Some((true, num, delim.unwrap() as char, ind + digits + 1 + off))
}

fn html_block_start(line: &str) -> bool {
    if indent_of(line) >= 4 {
        return false;
    }
    let t = line.trim_start();
    if !t.starts_with('<') {
        return false;
    }
    let rest = &t[1..];
    if rest.starts_with("!--") || rest.starts_with('?') || rest.starts_with('!') {
        return true;
    }
    let name_part = rest.strip_prefix('/').unwrap_or(rest);
    let name: String = name_part
        .chars()
        .take_while(|c| c.is_ascii_alphanumeric() || *c == '-')
        .collect();
    if name.is_empty() {
        return false;
    }
    let after = &name_part[name.len()..];
    after.is_empty()
        || after.starts_with(' ')
        || after.starts_with('>')
        || after.starts_with("/>")
}

fn footnote_def(line: &str) -> Option<(String, String)> {
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    if !t.starts_with("[^") {
        return None;
    }
    let close = t.find("]:")?;
    let label = t[2..close].to_string();
    if label.is_empty() || label.contains(' ') {
        return None;
    }
    Some((label, t[close + 2..].trim_start().to_string()))
}

fn is_table_delim(line: &str) -> bool {
    let t = line.trim();
    if t.is_empty() || !t.contains('-') {
        return false;
    }
    if !t.chars().all(|c| c == '-' || c == ':' || c == '|' || c == ' ') {
        return false;
    }
    let cells = split_table_row(t);
    !cells.is_empty()
        && cells.iter().all(|c| {
            let c = c.trim();
            !c.is_empty()
                && c.chars().all(|x| x == '-' || x == ':')
                && c.chars().filter(|&x| x == '-').count() >= 1
        })
}

fn split_table_row(line: &str) -> Vec<String> {
    let mut t = line.trim();
    if t.starts_with('|') {
        t = &t[1..];
    }
    if t.ends_with('|') && !t.ends_with("\\|") {
        t = &t[..t.len() - 1];
    }
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut escaped = false;
    for c in t.chars() {
        if escaped {
            if c != '|' {
                cur.push('\\');
            }
            cur.push(c);
            escaped = false;
        } else if c == '\\' {
            escaped = true;
        } else if c == '|' {
            cells.push(cur.clone());
            cur.clear();
        } else {
            cur.push(c);
        }
    }
    if escaped {
        cur.push('\\');
    }
    cells.push(cur);
    cells
}

impl Parser {
    fn collect_link_defs(&mut self, lines: &[String]) {
        let mut i = 0;
        let mut in_fence: Option<(char, usize)> = None;
        while i < lines.len() {
            let line = &lines[i];
            if let Some((c, n)) = in_fence {
                let t = line.trim_start();
                if t.starts_with(&c.to_string().repeat(n))
                    && t.chars().all(|x| x == c || x == ' ')
                {
                    in_fence = None;
                }
                i += 1;
                continue;
            }
            if let Some((c, n, _, _)) = fence_start(line) {
                in_fence = Some((c, n));
                i += 1;
                continue;
            }
            if footnote_def(line).is_none() {
                if let Some((label, dest, title, consumed)) = parse_link_def(lines, i) {
                    self.links.insert(
                        label.to_lowercase(),
                        LinkDef {
                            dest,
                            title,
                        },
                    );
                    i += consumed;
                    continue;
                }
            }
            i += 1;
        }
    }

    fn blocks(&self, lines: &[String]) -> Vec<Token> {
        let mut out = Vec::new();
        let mut i = 0;
        let mut para: Vec<String> = Vec::new();
        macro_rules! flush {
            () => {
                if !para.is_empty() {
                    let text = para.join("\n");
                    para.clear();
                    let inner = self.inline(&text);
                    if !inner.is_empty() {
                        out.push(make_paragraph(inner));
                    }
                }
            };
        }
        while i < lines.len() {
            let line = &lines[i];
            if is_blank(line) {
                flush!();
                i += 1;
                continue;
            }
            // Setext heading
            if !para.is_empty() {
                if let Some(level) = setext_level(line) {
                    if level == 1 || !is_thematic_break(line) {
                        let text = para.join("\n");
                        para.clear();
                        out.push(Token::Header(level, self.inline(&text)));
                        i += 1;
                        continue;
                    }
                }
            }
            if is_thematic_break(line) {
                flush!();
                out.push(Token::Rule);
                i += 1;
                continue;
            }
            if let Some((level, content)) = atx_heading(line) {
                flush!();
                out.push(Token::Header(level, self.inline(&content)));
                i += 1;
                continue;
            }
            if let Some((c, n, ind, info)) = fence_start(line) {
                flush!();
                let mut body = Vec::new();
                i += 1;
                while i < lines.len() {
                    let l = &lines[i];
                    let t = l.trim_start();
                    if indent_of(l) < 4
                        && t.starts_with(&c.to_string().repeat(n))
                        && t.chars().all(|x| x == c || x == ' ')
                    {
                        i += 1;
                        break;
                    }
                    let stripped = if indent_of(l) >= ind {
                        l[ind..].to_string()
                    } else {
                        l.trim_start().to_string()
                    };
                    body.push(stripped);
                    i += 1;
                }
                let mut content = body.join("\n");
                content.push('\n');
                let lang = info.split_whitespace().next().unwrap_or("").to_string();
                out.push(Token::CodeBlock(lang, content));
                continue;
            }
            if para.is_empty() && indent_of(line) >= 4 {
                let mut body = Vec::new();
                while i < lines.len() {
                    let l = &lines[i];
                    if is_blank(l) {
                        // look ahead
                        let mut j = i;
                        while j < lines.len() && is_blank(&lines[j]) {
                            j += 1;
                        }
                        if j < lines.len() && indent_of(&lines[j]) >= 4 {
                            for _ in i..j {
                                body.push(String::new());
                            }
                            i = j;
                            continue;
                        }
                        break;
                    }
                    if indent_of(l) < 4 {
                        break;
                    }
                    body.push(l[4..].to_string());
                    i += 1;
                }
                let mut content = body.join("\n");
                content.push('\n');
                out.push(Token::CodeBlock(String::new(), content));
                continue;
            }
            if line.trim_start().starts_with('>') && indent_of(line) < 4 {
                flush!();
                let mut body = Vec::new();
                while i < lines.len() {
                    let l = &lines[i];
                    if is_blank(l) {
                        break;
                    }
                    let t = l.trim_start();
                    if t.starts_with('>') {
                        let rest = &t[1..];
                        let rest = rest.strip_prefix(' ').unwrap_or(rest);
                        body.push(rest.to_string());
                    } else if indent_of(l) < 4 && (atx_heading(l).is_some() || is_thematic_break(l))
                    {
                        break;
                    } else {
                        body.push(l.clone());
                    }
                    i += 1;
                }
                // consume following blank-separated continuation of the quote
                while i < lines.len() && is_blank(&lines[i]) {
                    let mut j = i;
                    while j < lines.len() && is_blank(&lines[j]) {
                        j += 1;
                    }
                    if j < lines.len() && lines[j].trim_start().starts_with('>') {
                        for _ in i..j {
                            body.push(String::new());
                        }
                        i = j;
                        while i < lines.len() {
                            let l = &lines[i];
                            if is_blank(l) {
                                break;
                            }
                            let t = l.trim_start();
                            if t.starts_with('>') {
                                let rest = &t[1..];
                                let rest = rest.strip_prefix(' ').unwrap_or(rest);
                                body.push(rest.to_string());
                            } else {
                                body.push(l.clone());
                            }
                            i += 1;
                        }
                    } else {
                        break;
                    }
                }
                out.push(Token::BlockQuote(self.blocks(&body)));
                continue;
            }
            if let Some((label, first)) = footnote_def(line) {
                flush!();
                let mut body = vec![first];
                i += 1;
                while i < lines.len() {
                    let l = &lines[i];
                    if is_blank(l) {
                        let mut j = i;
                        while j < lines.len() && is_blank(&lines[j]) {
                            j += 1;
                        }
                        if j < lines.len() && indent_of(&lines[j]) >= 4 {
                            for _ in i..j {
                                body.push(String::new());
                            }
                            i = j;
                            continue;
                        }
                        break;
                    }
                    if indent_of(l) >= 4 {
                        body.push(l[4..].to_string());
                        i += 1;
                    } else if footnote_def(l).is_some()
                        || atx_heading(l).is_some()
                        || is_thematic_break(l)
                        || list_marker(l).is_some()
                    {
                        break;
                    } else {
                        body.push(l.clone());
                        i += 1;
                    }
                }
                out.push(Token::FootnoteDefinition(label, self.blocks(&body)));
                continue;
            }
            if para.is_empty() {
                if let Some((_, _, _, consumed)) = parse_link_def(lines, i) {
                    i += consumed;
                    continue;
                }
            }
            // table
            if i + 1 < lines.len()
                && line.contains('|')
                && is_table_delim(&lines[i + 1])
                && split_table_row(&lines[i + 1]).len() == split_table_row(line).len()
            {
                flush!();
                let headers = split_table_row(line);
                let ncols = headers.len();
                let mut rows = Vec::new();
                let head: Vec<Token> = headers
                    .iter()
                    .map(|c| Token::TableCell(self.inline(c.trim())))
                    .collect();
                rows.push(Token::TableHead(head));
                i += 2;
                while i < lines.len() && !is_blank(&lines[i]) && lines[i].contains('|') {
                    let mut cells = split_table_row(&lines[i]);
                    cells.resize(ncols, String::new());
                    let row: Vec<Token> = cells
                        .iter()
                        .map(|c| Token::TableCell(self.inline(c.trim())))
                        .collect();
                    rows.push(Token::TableRow(row));
                    i += 1;
                }
                out.push(Token::Table(ncols, rows));
                continue;
            }
            if let Some((ordered, start, marker, _)) = list_marker(line) {
                flush!();
                let (list, consumed) = self.parse_list(lines, i, ordered, marker);
                i += consumed;
                if ordered {
                    out.push(Token::OrderedList(start, list));
                } else {
                    out.push(Token::List(list));
                }
                continue;
            }
            if html_block_start(line) {
                flush!();
                let mut body = Vec::new();
                while i < lines.len() && !is_blank(&lines[i]) {
                    body.push(lines[i].clone());
                    i += 1;
                }
                let mut content = body.join("\n");
                content.push('\n');
                out.push(Token::Html(content));
                continue;
            }
            para.push(line.clone());
            i += 1;
        }
        flush!();
        out
    }

    fn parse_list(
        &self,
        lines: &[String],
        start: usize,
        ordered: bool,
        marker: char,
    ) -> (Vec<Token>, usize) {
        let mut items = Vec::new();
        let mut i = start;
        while i < lines.len() {
            let line = &lines[i];
            let m = match list_marker(line) {
                Some(m) => m,
                None => break,
            };
            if m.0 != ordered || m.2 != marker {
                break;
            }
            let content_indent = m.3;
            let first = if line.len() > content_indent {
                line[content_indent.min(line.len())..].to_string()
            } else {
                String::new()
            };
            let mut body = vec![first];
            i += 1;
            loop {
                if i >= lines.len() {
                    break;
                }
                let l = &lines[i];
                if is_blank(l) {
                    let mut j = i;
                    while j < lines.len() && is_blank(&lines[j]) {
                        j += 1;
                    }
                    if j < lines.len() && indent_of(&lines[j]) >= content_indent {
                        for _ in i..j {
                            body.push(String::new());
                        }
                        i = j;
                        continue;
                    }
                    break;
                }
                if indent_of(l) >= content_indent {
                    body.push(l[content_indent..].to_string());
                    i += 1;
                    continue;
                }
                if list_marker(l).is_some() || is_thematic_break(l) || atx_heading(l).is_some() {
                    break;
                }
                // lazy continuation
                body.push(l.trim_start().to_string());
                i += 1;
            }
            let mut tokens = self.blocks(&body);
            if tokens.is_empty() {
                tokens.push(Token::Paragraph(vec![]));
            }
            if let Some(task) = task_marker(&mut tokens) {
                items.push(Token::TaskItem(task, tokens));
            } else {
                items.push(Token::Item(tokens));
            }
            // Skip trailing blank lines between items
            let mut j = i;
            while j < lines.len() && is_blank(&lines[j]) {
                j += 1;
            }
            if j < lines.len() {
                if let Some(m2) = list_marker(&lines[j]) {
                    if m2.0 == ordered && m2.2 == marker {
                        i = j;
                        continue;
                    }
                }
            }
            break;
        }
        (items, i - start)
    }

    // ---------------------------------------------------------------- inline

    pub fn inline(&self, text: &str) -> Vec<Token> {
        let chars: Vec<char> = text.chars().collect();
        let mut tokens = self.inline_range(&chars, 0, chars.len());
        merge_strs(&mut tokens);
        tokens
    }

    fn inline_range(&self, c: &[char], from: usize, to: usize) -> Vec<Token> {
        let mut out: Vec<Token> = Vec::new();
        let mut buf = String::new();
        let mut i = from;
        macro_rules! flush {
            () => {
                if !buf.is_empty() {
                    out.push(Token::Str(std::mem::take(&mut buf)));
                }
            };
        }
        while i < to {
            let ch = c[i];
            match ch {
                '\\' if i + 1 < to && is_ascii_punct(c[i + 1]) => {
                    buf.push(c[i + 1]);
                    i += 2;
                }
                '\\' if i + 1 < to && c[i + 1] == '\n' => {
                    flush!();
                    out.push(Token::HardBreak);
                    i += 2;
                    while i < to && (c[i] == ' ' || c[i] == '\t') {
                        i += 1;
                    }
                }
                '\n' => {
                    let spaces = buf.chars().rev().take_while(|&x| x == ' ').count();
                    if spaces >= 2 {
                        let n = buf.len() - spaces;
                        buf.truncate(n);
                        flush!();
                        out.push(Token::HardBreak);
                    } else {
                        while buf.ends_with(' ') {
                            buf.pop();
                        }
                        flush!();
                        out.push(Token::SoftBreak);
                    }
                    i += 1;
                    while i < to && (c[i] == ' ' || c[i] == '\t') {
                        i += 1;
                    }
                }
                '`' => {
                    let n = count_run(c, i, to, '`');
                    if let Some(end) = find_run(c, i + n, to, '`', n) {
                        flush!();
                        let mut content: String = c[i + n..end].iter().collect();
                        content = content.replace('\n', " ");
                        if content.len() >= 2
                            && content.starts_with(' ')
                            && content.ends_with(' ')
                            && content.trim() != ""
                        {
                            content = content[1..content.len() - 1].to_string();
                        }
                        out.push(Token::Code(content));
                        i = end + n;
                    } else {
                        for _ in 0..n {
                            buf.push('`');
                        }
                        i += n;
                    }
                }
                '&' => {
                    if let Some((entity, len)) = parse_entity(c, i, to) {
                        buf.push_str(&entity);
                        i += len;
                    } else {
                        buf.push('&');
                        i += 1;
                    }
                }
                '<' => {
                    if let Some((token, len)) = self.parse_autolink(c, i, to) {
                        flush!();
                        out.push(token);
                        i += len;
                    } else if let Some(len) = html_tag_len(c, i, to) {
                        flush!();
                        out.push(Token::Html(c[i..i + len].iter().collect()));
                        i += len;
                    } else {
                        buf.push('<');
                        i += 1;
                    }
                }
                '!' if i + 1 < to && c[i + 1] == '[' => {
                    if let Some((token, len)) = self.parse_link(c, i + 1, to, true) {
                        flush!();
                        out.push(token);
                        i += len + 1;
                    } else {
                        buf.push('!');
                        i += 1;
                    }
                }
                '[' => {
                    if c.get(i + 1) == Some(&'^') {
                        if let Some(end) = find_char(c, i + 2, to, ']') {
                            let label: String = c[i + 2..end].iter().collect();
                            if !label.is_empty() && !label.contains(' ') {
                                flush!();
                                out.push(Token::FootnoteReference(label));
                                i = end + 1;
                                continue;
                            }
                        }
                    }
                    if let Some((token, len)) = self.parse_link(c, i, to, false) {
                        flush!();
                        out.push(token);
                        i += len;
                    } else {
                        buf.push('[');
                        i += 1;
                    }
                }
                '*' | '_' => {
                    let n = count_run(c, i, to, ch);
                    if let Some((inner_start, inner_end, consumed)) =
                        self.find_emph(c, i, to, ch, n)
                    {
                        flush!();
                        let inner = self.inline_range(c, inner_start, inner_end);
                        let delim = inner_start - i;
                        out.push(wrap_emph(delim, inner));
                        i += consumed;
                    } else {
                        for _ in 0..n {
                            buf.push(ch);
                        }
                        i += n;
                    }
                }
                '~' => {
                    let n = count_run(c, i, to, '~');
                    let effective = if n > 2 { 0 } else { n };
                    if effective > 0 {
                        if let Some(end) = find_run_exact(c, i + n, to, '~', n) {
                            flush!();
                            let inner = self.inline_range(c, i + n, end);
                            if n == 1 && self.opts.superscript {
                                out.push(Token::Subscript(inner));
                            } else {
                                out.push(Token::Strikethrough(inner));
                            }
                            i = end + n;
                            continue;
                        }
                    }
                    for _ in 0..n.max(1) {
                        buf.push('~');
                    }
                    i += n.max(1);
                }
                '^' if self.opts.superscript => {
                    if let Some(end) = find_char(c, i + 1, to, '^') {
                        if end > i + 1 {
                            flush!();
                            let inner = self.inline_range(c, i + 1, end);
                            out.push(Token::Superscript(inner));
                            i = end + 1;
                            continue;
                        }
                    }
                    buf.push('^');
                    i += 1;
                }
                _ => {
                    buf.push(ch);
                    i += 1;
                }
            }
        }
        flush!();
        out
    }

    fn parse_autolink(&self, c: &[char], i: usize, to: usize) -> Option<(Token, usize)> {
        let end = find_char(c, i + 1, to, '>')?;
        let content: String = c[i + 1..end].iter().collect();
        if content.is_empty() || content.contains(' ') || content.contains('<') {
            return None;
        }
        let scheme_end = content.find(':');
        if let Some(pos) = scheme_end {
            let scheme = &content[..pos];
            if !scheme.is_empty()
                && scheme.chars().next().unwrap().is_ascii_alphabetic()
                && scheme
                    .chars()
                    .all(|x| x.is_ascii_alphanumeric() || x == '+' || x == '-' || x == '.')
            {
                return Some((
                    Token::Link(
                        content.clone(),
                        String::new(),
                        vec![Token::Str(content)],
                    ),
                    end - i + 1,
                ));
            }
        }
        if content.contains('@') && !content.contains('/') {
            return Some((
                Token::Link(
                    format!("mailto:{}", content),
                    String::new(),
                    vec![Token::Str(content)],
                ),
                end - i + 1,
            ));
        }
        None
    }

    fn parse_link(&self, c: &[char], i: usize, to: usize, image: bool) -> Option<(Token, usize)> {
        // c[i] == '['
        let mut depth = 0;
        let mut j = i;
        let mut close = None;
        while j < to {
            match c[j] {
                '\\' => j += 1,
                '[' => depth += 1,
                ']' => {
                    depth -= 1;
                    if depth == 0 {
                        close = Some(j);
                        break;
                    }
                }
                '`' => {
                    let n = count_run(c, j, to, '`');
                    if let Some(e) = find_run(c, j + n, to, '`', n) {
                        j = e + n - 1;
                    }
                }
                _ => {}
            }
            j += 1;
        }
        let close = close?;
        let text_tokens = self.inline_range(c, i + 1, close);
        let label: String = c[i + 1..close].iter().collect();
        let mut k = close + 1;
        if k < to && c[k] == '(' {
            let mut depth = 1;
            let mut m = k + 1;
            while m < to && depth > 0 {
                match c[m] {
                    '\\' => m += 1,
                    '(' => depth += 1,
                    ')' => depth -= 1,
                    _ => {}
                }
                if depth == 0 {
                    break;
                }
                m += 1;
            }
            if m < to {
                let inner: String = c[k + 1..m].iter().collect();
                let (dest, title) = split_dest_title(&inner);
                let total = m + 1 - i;
                return Some((make_link(image, dest, title, text_tokens), total));
            }
        }
        if k < to && c[k] == '[' {
            if let Some(e) = find_char(c, k + 1, to, ']') {
                let refname: String = c[k + 1..e].iter().collect();
                let key = if refname.trim().is_empty() {
                    label.clone()
                } else {
                    refname
                };
                if let Some(def) = self.links.get(&key.to_lowercase()) {
                    return Some((
                        make_link(image, def.dest.clone(), def.title.clone(), text_tokens),
                        e + 1 - i,
                    ));
                }
                return None;
            }
        }
        if let Some(def) = self.links.get(&label.to_lowercase()) {
            return Some((
                make_link(image, def.dest.clone(), def.title.clone(), text_tokens),
                close + 1 - i,
            ));
        }
        let _ = k;
        None
    }

    fn find_emph(
        &self,
        c: &[char],
        i: usize,
        to: usize,
        ch: char,
        n: usize,
    ) -> Option<(usize, usize, usize)> {
        // Opening delimiter must be followed by non-space
        if i + n >= to || c[i + n].is_whitespace() {
            return None;
        }
        let use_n = if n >= 3 { 3 } else { n };
        let mut j = i + n;
        while j < to {
            if c[j] == '\\' {
                j += 2;
                continue;
            }
            if c[j] == '`' {
                let bn = count_run(c, j, to, '`');
                if let Some(e) = find_run(c, j + bn, to, '`', bn) {
                    j = e + bn;
                    continue;
                }
            }
            if c[j] == ch {
                let m = count_run(c, j, to, ch);
                if c[j - 1].is_whitespace() {
                    j += m;
                    continue;
                }
                if m >= use_n {
                    return Some((i + use_n, j, j + use_n - i));
                }
                j += m;
                continue;
            }
            j += 1;
        }
        None
    }
}

fn make_link(image: bool, dest: String, title: String, text: Vec<Token>) -> Token {
    if image {
        Token::Image(dest, title, text)
    } else {
        Token::Link(dest, title, text)
    }
}

fn wrap_emph(n: usize, inner: Vec<Token>) -> Token {
    match n {
        1 => Token::Emphasis(inner),
        2 => Token::Strong(inner),
        _ => Token::Emphasis(vec![Token::Strong(inner)]),
    }
}

fn task_marker(tokens: &mut Vec<Token>) -> Option<bool> {
    let first = tokens.first_mut()?;
    let inner = first.inner_mut()?;
    let s = match inner.first_mut() {
        Some(Token::Str(s)) => s,
        _ => return None,
    };
    let checked = if s.starts_with("[ ] ") || s.starts_with("[ ]") {
        false
    } else if s.starts_with("[x] ") || s.starts_with("[X] ") || s.starts_with("[x]") {
        true
    } else {
        return None;
    };
    let rest = s[3..].strip_prefix(' ').unwrap_or(&s[3..]).to_string();
    *s = rest;
    Some(checked)
}

fn make_paragraph(inner: Vec<Token>) -> Token {
    Token::Paragraph(inner)
}

fn count_run(c: &[char], i: usize, to: usize, ch: char) -> usize {
    let mut n = 0;
    while i + n < to && c[i + n] == ch {
        n += 1;
    }
    n
}

fn find_run(c: &[char], from: usize, to: usize, ch: char, n: usize) -> Option<usize> {
    let mut i = from;
    while i < to {
        if c[i] == ch {
            let m = count_run(c, i, to, ch);
            if m == n {
                return Some(i);
            }
            i += m;
        } else {
            i += 1;
        }
    }
    None
}

fn find_run_exact(c: &[char], from: usize, to: usize, ch: char, n: usize) -> Option<usize> {
    let mut i = from;
    while i < to {
        if c[i] == ch {
            let m = count_run(c, i, to, ch);
            if m >= n {
                return Some(i);
            }
            i += m;
        } else {
            i += 1;
        }
    }
    None
}

fn find_char(c: &[char], from: usize, to: usize, ch: char) -> Option<usize> {
    let mut i = from;
    while i < to {
        if c[i] == '\\' {
            i += 2;
            continue;
        }
        if c[i] == ch {
            return Some(i);
        }
        i += 1;
    }
    None
}

fn is_ascii_punct(c: char) -> bool {
    matches!(c,
        '!' | '"' | '#' | '$' | '%' | '&' | '\'' | '(' | ')' | '*' | '+' | ',' | '-' | '.' | '/'
        | ':' | ';' | '<' | '=' | '>' | '?' | '@' | '[' | '\\' | ']' | '^' | '_' | '`' | '{'
        | '|' | '}' | '~')
}

fn html_tag_len(c: &[char], i: usize, to: usize) -> Option<usize> {
    if c.get(i) != Some(&'<') {
        return None;
    }
    let mut j = i + 1;
    if j < to && c[j] == '!' {
        // comment / declaration
        let end = find_char(c, j, to, '>')?;
        return Some(end + 1 - i);
    }
    if j < to && c[j] == '/' {
        j += 1;
    }
    if j >= to || !c[j].is_ascii_alphabetic() {
        return None;
    }
    while j < to && (c[j].is_ascii_alphanumeric() || c[j] == '-') {
        j += 1;
    }
    while j < to && c[j] != '>' {
        if c[j] == '<' {
            return None;
        }
        j += 1;
    }
    if j >= to {
        return None;
    }
    Some(j + 1 - i)
}

fn split_dest_title(inner: &str) -> (String, String) {
    let s = inner.trim();
    if s.is_empty() {
        return (String::new(), String::new());
    }
    let (dest, rest) = if s.starts_with('<') {
        match s.find('>') {
            Some(p) => (s[1..p].to_string(), s[p + 1..].trim().to_string()),
            None => (s.to_string(), String::new()),
        }
    } else {
        let mut depth = 0;
        let mut end = s.len();
        for (idx, ch) in s.char_indices() {
            match ch {
                '(' => depth += 1,
                ')' => depth -= 1,
                c if c.is_whitespace() && depth == 0 => {
                    end = idx;
                    break;
                }
                _ => {}
            }
        }
        (s[..end].to_string(), s[end..].trim().to_string())
    };
    let title = if rest.len() >= 2 {
        let first = rest.chars().next().unwrap();
        let last = rest.chars().last().unwrap();
        if (first == '"' && last == '"')
            || (first == '\'' && last == '\'')
            || (first == '(' && last == ')')
        {
            rest[1..rest.len() - 1].to_string()
        } else {
            String::new()
        }
    } else {
        String::new()
    };
    (unescape(&dest), unescape(&title))
}

fn unescape(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            if let Some(&next) = chars.peek() {
                if is_ascii_punct(next) {
                    out.push(next);
                    chars.next();
                    continue;
                }
            }
        }
        out.push(c);
    }
    out
}

fn parse_link_def(lines: &[String], i: usize) -> Option<(String, String, String, usize)> {
    let line = &lines[i];
    if indent_of(line) >= 4 {
        return None;
    }
    let t = line.trim_start();
    if !t.starts_with('[') || t.starts_with("[^") {
        return None;
    }
    let chars: Vec<char> = t.chars().collect();
    let close = find_char(&chars, 1, chars.len(), ']')?;
    if chars.get(close + 1) != Some(&':') {
        return None;
    }
    let label: String = chars[1..close].iter().collect();
    if label.trim().is_empty() {
        return None;
    }
    let rest: String = chars[close + 2..].iter().collect();
    let rest = rest.trim().to_string();
    if rest.is_empty() {
        return None;
    }
    let (dest, title) = split_dest_title(&rest);
    if dest.is_empty() {
        return None;
    }
    Some((label, dest, title, 1))
}

fn parse_entity(c: &[char], i: usize, to: usize) -> Option<(String, usize)> {
    if c.get(i) != Some(&'&') {
        return None;
    }
    let end = {
        let mut j = i + 1;
        let mut found = None;
        while j < to && j < i + 33 {
            if c[j] == ';' {
                found = Some(j);
                break;
            }
            if !(c[j].is_ascii_alphanumeric() || c[j] == '#') {
                break;
            }
            j += 1;
        }
        found?
    };
    let name: String = c[i + 1..end].iter().collect();
    let len = end + 1 - i;
    if let Some(num) = name.strip_prefix("#x").or_else(|| name.strip_prefix("#X")) {
        let n = u32::from_str_radix(num, 16).ok()?;
        return Some((char::from_u32(n).unwrap_or('\u{fffd}').to_string(), len));
    }
    if let Some(num) = name.strip_prefix('#') {
        let n: u32 = num.parse().ok()?;
        return Some((char::from_u32(n).unwrap_or('\u{fffd}').to_string(), len));
    }
    let ch = named_entity(&name)?;
    Some((ch.to_string(), len))
}

fn named_entity(name: &str) -> Option<&'static str> {
    let table: &[(&str, &str)] = &[
        ("amp", "&"),
        ("lt", "<"),
        ("gt", ">"),
        ("quot", "\""),
        ("apos", "'"),
        ("nbsp", "\u{a0}"),
        ("copy", "©"),
        ("reg", "®"),
        ("trade", "™"),
        ("hellip", "…"),
        ("mdash", "—"),
        ("ndash", "–"),
        ("lsquo", "‘"),
        ("rsquo", "’"),
        ("ldquo", "“"),
        ("rdquo", "”"),
        ("laquo", "«"),
        ("raquo", "»"),
        ("deg", "°"),
        ("plusmn", "±"),
        ("frac12", "½"),
        ("times", "×"),
        ("divide", "÷"),
        ("eacute", "é"),
        ("egrave", "è"),
        ("agrave", "à"),
        ("ccedil", "ç"),
        ("uuml", "ü"),
        ("ouml", "ö"),
        ("auml", "ä"),
        ("szlig", "ß"),
        ("euro", "€"),
        ("pound", "£"),
        ("yen", "¥"),
        ("cent", "¢"),
        ("sect", "§"),
        ("para", "¶"),
        ("middot", "·"),
        ("bull", "•"),
        ("dagger", "†"),
        ("Dagger", "‡"),
        ("permil", "‰"),
        ("lsaquo", "‹"),
        ("rsaquo", "›"),
        ("oline", "‾"),
        ("frasl", "⁄"),
        ("larr", "←"),
        ("uarr", "↑"),
        ("rarr", "→"),
        ("darr", "↓"),
        ("harr", "↔"),
        ("infin", "∞"),
        ("ne", "≠"),
        ("le", "≤"),
        ("ge", "≥"),
        ("alpha", "α"),
        ("beta", "β"),
        ("gamma", "γ"),
        ("delta", "δ"),
        ("pi", "π"),
        ("sigma", "σ"),
        ("omega", "ω"),
        ("Omega", "Ω"),
    ];
    table.iter().find(|(k, _)| *k == name).map(|(_, v)| *v)
}

pub fn merge_strs(tokens: &mut Vec<Token>) {
    let mut i = 0;
    while i + 1 < tokens.len() {
        let merge = matches!(
            (&tokens[i], &tokens[i + 1]),
            (Token::Str(_), Token::Str(_))
        );
        if merge {
            let next = match tokens.remove(i + 1) {
                Token::Str(s) => s,
                _ => unreachable!(),
            };
            if let Token::Str(ref mut s) = tokens[i] {
                s.push_str(&next);
            }
        } else {
            i += 1;
        }
    }
    for t in tokens.iter_mut() {
        if let Some(inner) = t.inner_mut() {
            merge_strs(inner);
        }
    }
}

