//! Runtime storage of the book options.

use crate::lang::lformat;
use crate::options::{self, OptType};
use crate::yaml::Yaml;
use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    StrVec(Vec<String>),
    Path(String),
}

impl Value {
    pub fn as_str(&self) -> Option<&str> {
        match *self {
            Value::Str(ref s) | Value::Path(ref s) => Some(s),
            _ => None,
        }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match *self {
            Value::Bool(b) => Some(b),
            _ => None,
        }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match *self {
            Value::Int(i) => Some(i),
            _ => None,
        }
    }
}

pub struct Options {
    map: HashMap<String, Value>,
    /// Keys that were explicitly set (as opposed to defaulted)
    pub set_keys: Vec<String>,
    pub deprecated: Vec<(String, String)>,
}

fn default_value(desc: &options::OptDesc) -> Option<Value> {
    let raw = desc.default?;
    // The stored default is written the way it appears in the source table:
    // strip the surrounding quotes if there are any.
    let unquoted = if raw.len() >= 2 && raw.starts_with('"') && raw.ends_with('"') {
        raw[1..raw.len() - 1].replace("\\\\", "\\")
    } else {
        raw.to_string()
    };
    Some(match desc.otype {
        OptType::Bool => Value::Bool(unquoted == "true"),
        OptType::Int => Value::Int(unquoted.parse().unwrap_or(0)),
        OptType::Path => Value::Path(unquoted),
        OptType::StrVec => Value::StrVec(Vec::new()),
        _ => Value::Str(unquoted),
    })
}

impl Options {
    pub fn new() -> Options {
        let mut map = HashMap::new();
        for desc in options::OPTIONS {
            match desc.otype {
                OptType::Section | OptType::Alias(_) | OptType::Removed => continue,
                _ => {}
            }
            if let Some(v) = default_value(desc) {
                map.insert(desc.key.to_string(), v);
            }
        }
        for desc in options::HIDDEN {
            if let Some(v) = default_value(desc) {
                map.insert(desc.key.to_string(), v);
            }
        }
        Options {
            map,
            set_keys: Vec::new(),
            deprecated: Vec::new(),
        }
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.map.get(key)
    }

    pub fn is_set(&self, key: &str) -> bool {
        self.set_keys.iter().any(|k| k == key)
    }

    pub fn get_str(&self, key: &str) -> Option<&str> {
        self.map.get(key).and_then(|v| v.as_str())
    }

    pub fn get_string(&self, key: &str) -> String {
        self.get_str(key).unwrap_or("").to_string()
    }

    pub fn get_bool(&self, key: &str) -> bool {
        self.map
            .get(key)
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
    }

    pub fn get_bool_opt(&self, key: &str) -> Option<bool> {
        self.map.get(key).and_then(|v| v.as_bool())
    }

    pub fn get_i64(&self, key: &str) -> i64 {
        self.map.get(key).and_then(|v| v.as_i64()).unwrap_or(0)
    }

    pub fn get_strvec(&self, key: &str) -> Vec<String> {
        match self.map.get(key) {
            Some(Value::StrVec(v)) => v.clone(),
            _ => Vec::new(),
        }
    }

    pub fn set_raw(&mut self, key: &str, value: Value) {
        self.map.insert(key.to_string(), value);
        if !self.set_keys.iter().any(|k| k == key) {
            self.set_keys.push(key.to_string());
        }
    }

    /// Resolve deprecated keys, returning the canonical key. Warnings are
    /// accumulated so that the caller can display them.
    fn resolve(&mut self, key: &str) -> Result<String, String> {
        let mut current = key.to_string();
        for _ in 0..10 {
            let desc = options::find_any(&current);
            match desc {
                None => {
                    return Err(format!(
                        "{}unrecognized key '{}'",
                        lformat!("Error converting BookOption: "),
                        current
                    ))
                }
                Some(d) => match d.otype {
                    OptType::Alias(target) => {
                        self.deprecated
                            .push((current.clone(), target.to_string()));
                        current = target.to_string();
                    }
                    OptType::Removed => {
                        return Err(format!(
                            "{}key '{}' has been deprecated.",
                            lformat!("Error converting BookOption: "),
                            current
                        ))
                    }
                    _ => return Ok(current),
                },
            }
        }
        Ok(current)
    }

    pub fn set_yaml(&mut self, key: &str, value: &Yaml) -> Result<(), String> {
        let key = self.resolve(key)?;
        let desc = options::find_any(&key).unwrap();
        let prefix = lformat!("Error converting BookOption: ");
        let v = match desc.otype {
            OptType::Bool => match *value {
                Yaml::Boolean(b) => Value::Bool(b),
                _ => {
                    return Err(format!(
                        "{}expected a boolean as value for key '{}', found {:?}",
                        prefix, key, value
                    ))
                }
            },
            OptType::Int => match *value {
                Yaml::Integer(i) => Value::Int(i),
                _ => {
                    return Err(format!(
                        "{}expected an integer as value for key '{}', found {:?}",
                        prefix, key, value
                    ))
                }
            },
            OptType::Float => match *value {
                Yaml::Real(ref s) => Value::Float(s.parse().unwrap_or(0.0)),
                Yaml::Integer(i) => Value::Float(i as f64),
                _ => {
                    return Err(format!(
                        "{}could not parse '{:?}' as a float for key '{}'",
                        prefix, value, key
                    ))
                }
            },
            OptType::StrVec => match *value {
                Yaml::Array(ref a) => {
                    let mut v = Vec::new();
                    for item in a {
                        match *item {
                            Yaml::String(ref s) => v.push(s.clone()),
                            _ => {
                                return Err(format!(
                                    "{}expected a string as value for a list of strings for key '{}', found {:?}",
                                    prefix, key, item
                                ))
                            }
                        }
                    }
                    Value::StrVec(v)
                }
                Yaml::String(ref s) => {
                    Value::StrVec(s.split_whitespace().map(|x| x.to_string()).collect())
                }
                _ => {
                    return Err(format!(
                        "{}expected a list of strings as value for key '{}', found {:?}",
                        prefix, key, value
                    ))
                }
            },
            OptType::Path | OptType::Tpl => match *value {
                Yaml::String(ref s) => Value::Path(s.clone()),
                Yaml::Integer(i) => Value::Path(format!("{}", i)),
                Yaml::Real(ref s) => Value::Path(s.clone()),
                _ => {
                    return Err(format!(
                        "{}expected a string as value for key '{}', found {:?}",
                        prefix, key, value
                    ))
                }
            },
            _ => match *value {
                Yaml::String(ref s) => Value::Str(s.clone()),
                Yaml::Integer(i) => Value::Str(format!("{}", i)),
                Yaml::Real(ref s) => Value::Str(s.clone()),
                Yaml::Boolean(b) => Value::Str(format!("{}", b)),
                _ => {
                    return Err(format!(
                        "{}expected a string as value for key '{}', found {:?}",
                        prefix, key, value
                    ))
                }
            },
        };
        self.set_raw(&key, v);
        Ok(())
    }

    /// Set from a string that must be parsed as a YAML value
    pub fn set_from_str(&mut self, key: &str, value: &str) -> Result<(), String> {
        let docs = crate::yaml::load(value).map_err(|e| {
            format!(
                "{}{}",
                lformat!("Error converting BookOption: "),
                e.msg
            )
        })?;
        if docs.len() != 1 {
            return Err(format!(
                "{}value '{}' for key '{}' does not contain one and only one YAML value",
                lformat!("Error converting BookOption: "),
                value,
                key
            ));
        }
        self.set_yaml(key, &docs[0])
    }
}

