/// Translate then substitute the `{}` placeholders in order
pub fn lformat_args(en: &str, args: &[&dyn std::fmt::Display]) -> String {
    let pattern = translate(en);
    let mut out = String::new();
    let mut rest = pattern;
    let mut i = 0;
    while let Some(pos) = rest.find("{}") {
        out.push_str(&rest[..pos]);
        if i < args.len() {
            out.push_str(&format!("{}", args[i]));
            i += 1;
        }
        rest = &rest[pos + 2..];
    }
    out.push_str(rest);
    out
}

