    ($fmt:expr) => { $crate::lang::translate($fmt).to_string() };
    ($fmt:expr, $($arg:expr),* $(,)?) => {
        $crate::lang::lformat_args($fmt, &[$(&$arg as &dyn std::fmt::Display),*])
    };
}

