//! Runtime and output localization.

/// Language used for the messages Crowbook itself prints
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum UiLang {
    En,
    Fr,
}

static mut UI_LANG: UiLang = UiLang::En;

pub fn set_ui_lang(lang: &str) {
    let l = if lang.len() >= 2 { &lang[..2] } else { lang };
    let l = l.to_lowercase();
    unsafe {
        UI_LANG = if l == "fr" { UiLang::Fr } else { UiLang::En };
    }
}

pub fn ui_lang() -> UiLang {
    unsafe { UI_LANG }
}

/// Translate a message identified by its english version
pub fn lformat(en: &str) -> &'static str {
    if ui_lang() == UiLang::En {
        return leak(en);
    }
    for &(key, fr) in FR_MESSAGES {
        if key == en {
            return fr;
        }
    }
    leak(en)
}

fn leak(s: &str) -> &'static str {
    // The set of strings passed here is a small fixed set of literals
    Box::leak(s.to_string().into_boxed_str())
}

static FR_MESSAGES: &[(&str, &str)] = &[
