//! Common HTML rendering of the token tree.

use crate::book::{Book, Chapter, Number};
use crate::highlight;
use crate::templ;
use crate::token::{collect_text, Token};
use crate::toc::Toc;

pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}

pub fn escape_quotes(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

/// Wrap narrow non breaking spaces in a span so that they display correctly
pub fn escape_nb_spaces(s: &str) -> String {
    if !s.contains('\u{202f}') {
        return s.to_string();
    }
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\u{202f}' {
            // find beginning of the run
            let mut start = i;
            while start > 0 && !chars[start - 1].is_whitespace() {
                start -= 1;
            }
            let mut end = i + 1;
            loop {
                while end < chars.len()
                    && !chars[end].is_whitespace()
                    && chars[end] != '\u{202f}'
                {
                    end += 1;
                }
                if end < chars.len() && chars[end] == '\u{202f}' {
                    end += 1;
                    continue;
                }
                break;
            }
            // rewind the already emitted part of the run
            let emitted: String = chars[start..i].iter().collect();
            if !emitted.is_empty() {
                let n = out.len() - emitted.len();
                out.truncate(n);
            }
            out.push_str("<span class = \"nnbsp\">");
            for c in &chars[start..end] {
                if *c == '\u{202f}' {
                    out.push_str("&#160;");
                } else {
                    out.push(*c);
                }
            }
            out.push_str("</span>");
            i = end;
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    out
}

pub struct HtmlRenderer<'a> {
    pub book: &'a Book,
    pub link_number: usize,
    pub para_number: usize,
    pub numbers: [i32; 8],
    pub part_number: i32,
    pub chapter_number: i32,
    pub current_hide: bool,
    pub current_numbered: bool,
    pub current_file: usize,
    pub footnotes: Vec<(String, String)>,
    pub toc: Toc,
    pub escape_nb: bool,
    pub verbatim: bool,
    pub inline_toc_only: bool,
    /// Prefix put before the `#link-x` anchors (used by the multifile renderer)
    pub link_prefix: String,
    pub html_as_text: bool,
    pub proofread: bool,
    pub first_para: bool,
    pub in_table_head: bool,
}

impl<'a> HtmlRenderer<'a> {
    pub fn new(book: &'a Book) -> HtmlRenderer<'a> {
        HtmlRenderer {
            book,
            link_number: 0,
            para_number: 0,
            numbers: [0; 8],
            part_number: 0,
            chapter_number: 0,
            current_hide: false,
            current_numbered: true,
            current_file: 0,
            footnotes: Vec::new(),
            toc: Toc::new(),
            escape_nb: true,
            verbatim: false,
            inline_toc_only: false,
            link_prefix: String::new(),
            html_as_text: book.options.get_bool("crowbook.html_as_text"),
            proofread: false,
            first_para: false,
            in_table_head: false,
        }
    }

    pub fn text(&self, s: &str) -> String {
        let escaped = escape_html(s);
        if self.escape_nb {
            escape_nb_spaces(&escaped)
        } else {
            escaped
        }
    }

    pub fn tokens(&mut self, tokens: &[Token]) -> String {
        let mut out = String::new();
        for t in tokens {
            out.push_str(&self.token(t));
        }
        out
    }

    fn number_prefix(&self, level: i32) -> String {
        let mut s = String::new();
        for i in 1..=level {
            s.push_str(&format!("{}.", self.numbers[i as usize]));
        }
        s.push(' ');
        s
    }

    pub fn start_chapter(&mut self, chapter: &Chapter, index: usize) {
        self.current_file = index;
        self.current_hide = matches!(chapter.number, Number::Hidden);
        self.current_numbered = matches!(
            chapter.number,
            Number::Default | Number::Specified(_) | Number::DefaultPart | Number::SpecifiedPart(_)
        );
        self.para_number = 0;
    }

    fn header(&mut self, level: i32, content: &[Token]) -> String {
        self.link_number += 1;
        let link = self.link_number;
        let title_html = {
            let saved = self.verbatim;
            self.verbatim = saved;
            self.tokens(content)
        };
        let raw = collect_text(content);
        if self.current_hide {
            return format!(
                "<h{lvl} id = \"link-{link}\"></h{lvl}>\n",
                lvl = level,
                link = link
            );
        }
        let num_depth = self.book.options.get_i64("rendering.num_depth") as i32;
        if level == 1 {
            let is_part = self.book.current_is_part;
            if is_part {
                return self.render_part(link, &title_html, &raw);
            }
            let numbered = self.current_numbered && num_depth >= 1;
            if numbered {
                self.chapter_number += 1;
                if let Number::Specified(n) = self.book.current_number {
                    self.chapter_number = n;
                }
                self.numbers[1] = self.chapter_number;
            }
            for i in 2..8 {
                self.numbers[i] = 0;
            }
            let number_str = if self.book.options.get_bool("rendering.chapter.roman_numerals") {
                crate::misc::roman(self.numbers[1])
            } else {
                format!("{}", self.numbers[1])
            };
            let header_word = self
                .book
                .options
                .get_str("rendering.chapter")
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .unwrap_or_else(|| self.book.lang().chapter.to_string());
            let mut ctx = templ::Context::new();
            templ::set_str(&mut ctx, "link", format!("{}", link));
            templ::set_bool(&mut ctx, "has_number", numbered);
            templ::set_str(&mut ctx, "header", header_word.clone());
            templ::set_str(&mut ctx, "number", number_str.clone());
            templ::set_bool(&mut ctx, "has_title", !raw.is_empty());
            templ::set_str(&mut ctx, "title", title_html.clone());
            let tpl = self.book.inline_template("html.chapter.template");
            let rendered = match tpl {
                Ok(t) => t.render(&ctx).unwrap_or_default(),
                Err(_) => String::new(),
            };
            // Register in the table of contents
            if !raw.is_empty() || numbered {
                let entry = self.toc_entry(numbered, &number_str, &header_word, &title_html, &raw);
                self.toc.add(1, format!("{}#link-{}", self.link_prefix, link), entry);
            }
            return rendered;
        }
        // Sub-headers
        let mut prefix = String::new();
        if self.current_numbered && num_depth >= level {
            self.numbers[level as usize] += 1;
            for i in (level as usize + 1)..8 {
                self.numbers[i] = 0;
            }
            prefix = self.number_prefix(level);
        }
        let entry = format!("{}{}", prefix, title_html);
        self.toc
            .add(level, format!("{}#link-{}", self.link_prefix, link), entry.clone());
        format!(
            "<h{lvl} id = \"link-{link}\">{content}</h{lvl}>\n",
            lvl = level,
            link = link,
            content = entry
        )
    }

    fn toc_entry(
        &self,
        numbered: bool,
        number: &str,
        header: &str,
        title: &str,
        raw: &str,
    ) -> String {
        let key = if self.book.current_is_part {
            "rendering.part.template"
        } else {
            "rendering.chapter.template"
        };
        let mut ctx = templ::Context::new();
        templ::set_str(&mut ctx, "number", number.to_string());
        templ::set_str(&mut ctx, "chapter_title", title.to_string());
        templ::set_str(&mut ctx, "part_title", title.to_string());
        templ::set_str(&mut ctx, "chapter_title_raw", raw.to_string());
        templ::set_str(&mut ctx, "part_title_raw", raw.to_string());
        templ::set_str(&mut ctx, "header", header.to_string());
        templ::set_bool(&mut ctx, "has_number", numbered);
        templ::set_bool(&mut ctx, "has_title", !raw.is_empty());
        match self.book.inline_template(key) {
            Ok(t) => match t.render(&ctx) {
                Ok(s) => {
                    if numbered {
                        s
                    } else {
                        title.to_string()
                    }
                }
                Err(_) => title.to_string(),
            },
            Err(_) => title.to_string(),
        }
    }

    fn render_part(&mut self, link: usize, title_html: &str, raw: &str) -> String {
        let numbered = self.current_numbered;
        if numbered {
            self.part_number += 1;
            if let Number::SpecifiedPart(n) = self.book.current_number {
                self.part_number = n;
            }
        }
        let number_str = if !numbered {
            String::new()
        } else if self.book.options.get_bool("rendering.part.roman_numerals") {
            crate::misc::roman(self.part_number)
        } else {
            format!("{}", self.part_number)
        };
        let header_word = if !numbered {
            String::new()
        } else {
            self.book
                .options
                .get_str("rendering.part")
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .unwrap_or_else(|| self.book.lang().part.to_string())
        };
        if self.book.options.get_bool("rendering.part.reset_counter") {
            self.chapter_number = 0;
        }
        let mut ctx = templ::Context::new();
        templ::set_str(&mut ctx, "link", format!("{}", link));
        templ::set_bool(&mut ctx, "has_number", numbered);
        templ::set_str(&mut ctx, "header", header_word.clone());
        templ::set_str(&mut ctx, "number", number_str.clone());
        templ::set_bool(&mut ctx, "has_title", !raw.is_empty());
        templ::set_str(&mut ctx, "title", title_html.to_string());
        let rendered = match self.book.inline_template("html.part.template") {
            Ok(t) => t.render(&ctx).unwrap_or_default(),
            Err(_) => String::new(),
        };
        let entry = self.toc_entry(numbered, &number_str, &header_word, title_html, raw);
        self.toc
            .add(1, format!("{}#link-{}", self.link_prefix, link), entry);
        rendered
    }

    pub fn token(&mut self, token: &Token) -> String {
        match *token {
            Token::Str(ref s) => self.text(s),
            Token::Paragraph(ref v) => {
                self.para_number += 1;
                let n = self.para_number;
                let content = self.tokens(v);
                format!("<p id = \"para-{}\">{}</p>\n", n, content)
            }
            Token::Header(level, ref v) => self.header(level, v),
            Token::Emphasis(ref v) => format!("<em>{}</em>", self.tokens(v)),
            Token::Strong(ref v) => format!("<b>{}</b>", self.tokens(v)),
            Token::Strikethrough(ref v) => format!("<del>{}</del>", self.tokens(v)),
            Token::Superscript(ref v) => format!("<sup>{}</sup>", self.tokens(v)),
            Token::Subscript(ref v) => format!("<sub>{}</sub>", self.tokens(v)),
            Token::Code(ref s) => format!("<code>{}</code>", escape_html(s)),
            Token::BlockQuote(ref v) => format!("<blockquote>{}</blockquote>\n", self.tokens(v)),
            Token::CodeBlock(ref lang, ref content) => self.code_block(lang, content),
            Token::List(ref v) => format!("<ul>\n{}</ul>\n", self.tokens(v)),
            Token::OrderedList(n, ref v) => {
                let start = if n != 1 {
                    format!(" start = \"{}\"", n)
                } else {
                    String::new()
                };
                format!("<ol{}>\n{}</ol>\n", start, self.tokens(v))
            }
            Token::Item(ref v) => format!("<li>{}</li>\n", self.tokens(v)),
            Token::TaskItem(checked, ref v) => {
                let c = if checked { "checked = \"\"" } else { "" };
                format!(
                    "<input type = \"checkbox\" disabled = \"\" {}/>{}",
                    c,
                    self.tokens(v)
                )
            }
            Token::Link(ref url, ref title, ref v) => {
                let content = self.tokens(v);
                let title_attr = if title.is_empty() {
                    String::new()
                } else {
                    format!(" title = \"{}\"", escape_quotes(title))
                };
                format!(
                    "<a href = \"{}\"{}>{}</a>",
                    escape_quotes(&self.book.resolve_link(url)),
                    title_attr,
                    content
                )
            }
            Token::Image(ref url, ref title, ref v) => {
                let alt = collect_text(v);
                format!(
                    "<img src = \"{}\" title = \"{}\" alt = \"{}\" />",
                    escape_quotes(&self.book.image_src(url)),
                    escape_quotes(title),
                    escape_quotes(&alt)
                )
            }
            Token::StandaloneImage(ref url, ref title, ref v) => {
                let alt = collect_text(v);
                format!(
                    "<div class = \"image\">\n  <img src = \"{}\" title = \"{}\" alt = \"{}\" />\n</div>\n",
                    escape_quotes(&self.book.image_src(url)),
                    escape_quotes(title),
                    escape_quotes(&alt)
                )
            }
            Token::Rule => String::from("<p class = \"rule\">***</p>\n"),
            Token::SoftBreak => String::from(" "),
            Token::HardBreak => String::from("<br />\n"),
            Token::FootnoteReference(ref label) => {
                let id = format!("{}-{}", self.current_file + 1, label);
                format!(
                    "<a class = \"footnote_reference\" href = \"#note-dest-{id}\" id = \"note-source-{id}\"><sup>[{label}]</sup></a>",
                    id = id,
                    label = escape_html(label)
                )
            }
            Token::FootnoteDefinition(ref label, ref v) => {
                let content = self.tokens(v);
                let id = format!("{}-{}", self.current_file + 1, label);
                if let Some(existing) = self.footnotes.iter_mut().find(|(l, _)| *l == id) {
                    existing.1 = content;
                } else {
                    self.footnotes.push((id, content));
                }
                String::new()
            }
            Token::Table(_, ref v) => format!(
                "<div class = \"table\">\n    <table>\n{}\n    </table>\n</div>\n",
                self.tokens(v)
            ),
            Token::TableHead(ref v) => {
                self.in_table_head = true;
                let s = format!("<tr>\n{}</tr>\n", self.tokens(v));
                self.in_table_head = false;
                s
            }
            Token::TableRow(ref v) => format!("<tr>\n{}</tr>\n", self.tokens(v)),
            Token::TableCell(ref v) => {
                let tag = if self.in_table_head { "th" } else { "td" };
                format!("<{t}>{c}</{t}>", t = tag, c = self.tokens(v))
            }
            Token::Html(ref s) => {
                if self.html_as_text {
                    self.text(s)
                } else {
                    String::new()
                }
            }
            Token::Annotation(_, ref v) => self.tokens(v),
        }
    }

    fn code_block(&mut self, lang: &str, content: &str) -> String {
        let mode = self.book.options.get_string("rendering.highlight");
        if mode == "syntect" {
            let theme = self.book.highlight_theme("html");
            format!("<pre>{}\n</pre>\n", highlight::html(content, lang, &theme))
        } else {
            let class = if lang.is_empty() {
                String::new()
            } else {
                format!(" class = \"language-{}\"", lang)
            };
            format!(
                "<pre><code{}>{}</code></pre>\n\n",
                class,
                escape_html(content)
            )
        }
    }

    pub fn render_notes(&mut self) -> String {
        if self.footnotes.is_empty() {
            return String::new();
        }
        let notes = std::mem::take(&mut self.footnotes);
        let mut out = String::new();
        out.push_str(&format!(
            "<section class = \"notes\" >\n <h2 class = \"notes\">{}</h2>\n<table class = \"notes\">\n",
            self.book.lang().notes
        ));
        for (id, content) in &notes {
            let label = id.splitn(2, '-').nth(1).unwrap_or("");
            out.push_str(&format!(
                "<tr class = \"notes\">\n <td class = \"note-number\">\n  <p class = \"note-number\">\n  <a rel = \"footnote\" href = \"#note-source-{id}\">[{label}]</a>\n</p>\n\n </td>\n <td class = \"note\">\n  <aside class = \"footnote\" id = \"note-dest-{id}\">{content}</aside>\n  </td>\n</tr>\n",
                id = id,
                label = escape_html(label),
                content = content
            ));
        }
        out.push_str("</table>\n</section>\n");
        out
    }
}

