//! Table of contents structure, rendered as nested HTML lists.

pub struct TocElement {
    pub level: i32,
    pub url: String,
    pub title: String,
    pub children: Vec<TocElement>,
}

pub struct Toc {
    pub elements: Vec<TocElement>,
}

impl Toc {
