//! Syntax highlighting.
//!
//! Only the "plain text" syntax is implemented: every line is emitted with the
//! theme's default foreground colour.

pub struct Theme {
    pub name: &'static str,
    pub fg: (u8, u8, u8),
}

pub fn theme(name: &str) -> Theme {
    let fg = match name {
        "Solarized (dark)" => (0x83, 0x94, 0x96),
        "Solarized (light)" => (0x65, 0x7b, 0x83),
        "base16-ocean.dark" => (0xc0, 0xc5, 0xce),
        "base16-ocean.light" => (0x4f, 0x5b, 0x66),
        "base16-eighties.dark" => (0xd3, 0xd0, 0xc8),
        "base16-mocha.dark" => (0xd0, 0xc8, 0xc6),
        _ => (0x32, 0x32, 0x32),
    };
    Theme {
        name: Box::leak(name.to_string().into_boxed_str()),
        fg,
    }
}

fn lines(content: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = 0;
    let bytes = content.as_bytes();
    for i in 0..bytes.len() {
        if bytes[i] == b'\n' {
            out.push(&content[start..i]);
            start = i + 1;
        }
    }
    if start < content.len() {
        out.push(&content[start..]);
    }
    out
}

pub fn html(content: &str, _lang: &str, theme_name: &str) -> String {
    let t = theme(theme_name);
    let mut out = String::new();
    for line in lines(content) {
        if !line.is_empty() {
            out.push_str(&format!(
                "<span style=\"color:#{:02x}{:02x}{:02x};\">{}</span>",
                t.fg.0,
                t.fg.1,
                t.fg.2,
                crate::html::escape_quotes(line)
            ));
        }
        out.push('\n');
    }
    out
}

/// Escape a string that appears inside a LaTeX code block
pub fn latex_code_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            ' ' => out.push_str("\\hphantom{ }\\allowbreak{}"),
            '(' => out.push_str("(\\allowbreak{}"),
            ')' => out.push_str(")\\allowbreak{}"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '%' => out.push_str("\\%"),
            '_' => out.push_str("\\_\\allowbreak{}"),
            '#' => out.push_str("\\#"),
            '$' => out.push_str("\\$"),
            '&' => out.push_str("\\&"),
            '^' => out.push_str("\\textasciicircum{}"),
            '~' => out.push_str("\\textasciitilde{}"),
            '\\' => out.push_str("\\textbackslash{}"),
            _ => out.push(c),
        }
    }
    out
}

pub fn latex(content: &str, _lang: &str, theme_name: &str) -> String {
    let t = theme(theme_name);
    let (r, g, b) = (
        t.fg.0 as f64 / 255.0,
        t.fg.1 as f64 / 255.0,
        t.fg.2 as f64 / 255.0,
    );
    let mut out = String::from("{\\sloppy ");
    for line in lines(content) {
        if !line.is_empty() {
            out.push_str(&format!(
                "\\textcolor[rgb]{{{}, {}, {}}}{{\\texttt{{{}}}}}",
                fmt_f32(r),
                fmt_f32(g),
                fmt_f32(b),
                latex_code_escape(line)
            ));
        }
        out.push_str("\\\\{}\n");
    }
    out.push_str("}\n");
    out
}

fn fmt_f32(v: f64) -> String {
    let s = format!("{}", v as f32);
    s
}

